import json,html,re
from pathlib import Path
root=Path(__file__).parent
prods=json.load(open(root/'assets/catalog.json',encoding='utf8'))['products']
def e(x):return html.escape(str(x),quote=True)
def path_img(v,view):
    g=next((x for x in v['gallery'] if x['view']==view),None)
    return 'assets/images/'+(g or v['gallery'][0])['filename']
def common_head(title,desc,base=''):
  return f'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#170000"><meta name="description" content="{e(desc)}"><title>{e(title)}</title><link rel="icon" type="image/png" href="{base}assets/images/starkit-logo-transparent.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="stylesheet" href="{base}assets/css/styles.css"><script>window.STARKIT_BASE={json.dumps(base or "./")}</script><script defer src="{base}assets/js/store-config.js"></script><script defer src="{base}assets/js/catalog-data.js"></script><script defer src="{base}assets/js/app.js"></script></head><body>'''
def nav(base=''):
 return f'''<div class="announcement"><span>STARKIT / DROP 01</span> • THE GRAPHIC ARCHIVE • DHAKA</div><div class="preview-banner"><strong>COLLECTION PREVIEW</strong> · Product artwork, availability and business terms are pending verification. Ordering is not yet open.</div><header class="header"><div class="shell nav-inner"><a class="brand" href="{base}index.html" aria-label="StarkiT home"><img src="{base}assets/images/starkit-logo-brand-original.png" width="125" height="53" alt="StarkiT official brand logo"><span class="brand-rule"></span><div class="brand-note">DROP 01<span>WEAR YOUR WORLD.</span></div></a><nav class="nav-links" id="mainNav"><a href="{base}index.html">Home</a><a href="{base}shop.html">The Collection</a><a href="{base}about.html">Our World</a><a href="{base}shipping.html">Information</a></nav><div class="nav-actions"><button class="icon-btn" type="button" data-open-cart aria-label="Open shopping bag">BAG <span class="count" data-cart-count>0</span></button><button id="menuToggle" aria-label="Toggle menu" aria-controls="mainNav" aria-expanded="false" class="icon-btn menu-toggle" type="button">☰</button></div></div></header>'''
def footer(base=''):
 return f'''<footer class="footer"><div class="shell"><div class="footer-top"><div><a href="{base}index.html"><img class="footer-logo" src="{base}assets/images/starkit-logo-brand-original.png" width="175" height="93" alt="StarkiT logo"></a><p class="footer-slogan">WEAR YOUR<br>WORLD.</p><p style="max-width:370px;color:#c8b6b7;line-height:1.6">Independent streetwear expression. Graphic stories. A collection designed around culture, community and individuality.</p></div><div><h4>DISCOVER</h4><nav><a href="{base}shop.html">All Designs</a><a href="{base}index.html#lookbook">Interactive Lookbook</a><a href="{base}about.html">Our World</a><a href="{base}index.html#collection">Drop 01</a></nav></div><div><h4>INFORMATION</h4><nav><a href="{base}shipping.html">Delivery &amp; Availability</a><a href="{base}returns.html">Returns &amp; Replacements</a><a href="{base}contact.html">Contact</a><a href="{base}privacy.html">Privacy</a><a href="{base}terms.html">Terms</a></nav></div></div><div class="footer-bottom"><span>© 2026 STARKIT. ALL RIGHTS RESERVED. · INTERNAL COLLECTION PREVIEW</span><span>CREATED FOR BANGLADESH · BDT PRICING</span></div></div></footer>'''
def overlays(base=''):
 return f'''<div class="overlay" id="overlay" aria-hidden="true"></div><aside class="drawer" id="cartDrawer" role="dialog" aria-label="Shopping bag" aria-modal="true"><div class="drawer-head"><h2>YOUR BAG <span class="pill">DROP 01</span></h2><button class="close-btn" data-close-cart aria-label="Close bag">×</button></div><div class="drawer-items" id="cartItems"></div><div class="drawer-foot" id="cartFoot" hidden><div class="summary"><span>SUBTOTAL</span><span id="cartSubtotal">৳0</span></div><p class="hint">Shipping fee and payment options will be finalized after seller verification.</p><a class="btn" href="{base}checkout.html">REVIEW CHECKOUT ↗</a></div></aside><div class="lightbox" id="zoom" role="dialog" aria-modal="true" aria-label="Enlarged product image"><button type="button" aria-label="Close zoom">CLOSE ×</button><img id="zoomImg" alt=""></div><div id="toast" role="status" aria-live="polite" hidden style="position:fixed;bottom:24px;left:50%;transform:translateX(-50%);z-index:110;background:#170000;color:white;padding:14px 20px;font-weight:700;max-width:95vw;text-align:center;box-shadow:0 12px 40px #0003"></div>'''
def scripts_end():return '</body></html>'
def make(filename,body,title,desc,base=''):
 dest=root/filename;dest.parent.mkdir(parents=True,exist_ok=True)
 dest.write_text(common_head(title,desc,base)+nav(base)+body+footer(base)+overlays(base)+scripts_end(),encoding='utf8')

