for p in prods:
  v=p['variants'][0];f=path_img(v,'front');slug=p['slug']
  def get_imgs():return ''.join(f'<img src="../assets/images/{e(g["filename"])}" alt="{e(p["name"])} {e(g["view"])}" loading="lazy">' for g in v['gallery'][:1])
  bb='''<main><div class="shell"><div class="crumb"><a href="../index.html">HOME</a> / <a href="../shop.html">THE COLLECTION</a> / '''+e(p['name'])+'''</div><div class="detail" data-detail-product="'''+p['id']+'''"><div class="detail-main"><div class="detail-photo" id="detailGallery" tabindex="0" role="button" aria-label="Zoom product image"><img src="../'''+f+'''" alt="'''+e(p['name'])+''' front"><span class="view-tag">FRONT VIEW</span></div><div id="detailThumbs" class="thumbs"></div><p class="hint">Tap the main image to enlarge · Select any thumbnail to view another angle.</p></div><div class="detail-info"><div class="eyebrow">'''+e(p['collection']).upper()+''' · DROP 01</div><h1>'''+e(p['name'])+'''</h1><span class="smallcaps muted">SKU · <span id="detailSku">'''+e(v['sku'])+'''</span></span><div class="detail-price" style="margin:17px 0">৳'''+format(p['price_bdt'],',')+'''</div><div class="separator"></div><div class="detail-choice"><strong>SELECT COLORWAY</strong><span class="smallcaps muted">'''+str(len(p['variants']))+''' AVAILABLE IN CATALOG</span></div><div id="detailColors" class="variant-buttons"></div><p class="description">'''+e(p['copy_en'])+'''</p><p class="description bn" lang="bn">'''+e(p['copy_bn'])+'''</p><div class="separator"></div><div id="detailSize"></div><button id="purchaseBtn" class="btn purchase-btn" type="button" disabled>PREVIEW — ORDERING NOT YET OPEN</button><p id="purchaseStatus" class="hint">This collection is currently under commercial review.</p><div class="specs"><div class="spec"><strong>THE DESIGN</strong><span>'''+e(p['front_back_detail'])+'''</span></div><div class="spec"><strong>FABRIC</strong><span>Seller description: brushed fleece, combed cotton, 330–350 GSM. Not independently confirmed.</span></div><div class="spec"><strong>FIT & SIZE</strong><span>Fit and garment measurements pending verification.</span></div><div class="spec"><strong>COLORWAYS</strong><span>'''+e(' / '.join(vv['color'] for vv in p['variants']))+'''</span></div><div class="spec"><strong>DESIGN ID</strong><span>'''+p['id']+'''</span></div></div><div class="rights-msg"><b>Collection preview:</b> Artwork rights, product stock, size measurements and commercial policies require review before public sales.</div><p style="margin:24px 0"><a href="'''+e(p['drive_folder_url'])+'''" target="_blank" rel="noopener noreferrer" class="link-arrow">VIEW ORIGINAL MEDIA FOLDER ↗</a></p><p><a class="link-arrow" href="../shop.html">← BACK TO THE COLLECTION</a></p></div></div></div></main>'''
  make('products/'+slug+'.html',bb,p['name']+' | StarkiT Drop 01',p['copy_en']+' StarkiT preview. Price ৳'+str(p['price_bdt'])+'.',base='../')

